def test_arithmetic_constant_folding(self, device):
    def test(fn):
        cfn = self.compile_fn(fn)
        expect = fn(3)
        actual = cfn(3)
        self.assertEqual(expect, actual)

    def add(x):
        return x + torch.zeros(3)

    test(add)

    def mul(x):
        return x * torch.ones(3)

    test(mul)

    def div(x):
        return x / torch.ones(3)

    test(div)

